/src/callout.typ:
// Pointed callouts: source anchors, native text layout, and one painted outline.
#import "@preview/elembic:1.1.1" as e

#let bubble-name(name) = if name.starts-with("bubble-") { name.slice(7) } else { name }
#let style-names = (
  "bubble-gap",
  "pointer-align",
  "pointer-size",
  "pointer-height",
  "pointer-width",
  "pointer-offset",
  "bubble-align",
  "bubble-fill",
  "bubble-stroke",
  "bubble-inset",
  "bubble-outset",
  "bubble-radius",
  "bubble-width",
)

// One schema owns both the bubble's defaults and callout-level overrides.
#let fields(entry: false, bubble: false) = {
  let field(name, ty, default, doc) = {
    let styling = name in style-names
    if bubble and not styling { return none }
    let inherit = entry or (not bubble and styling)
    e.field(
      if bubble { bubble-name(name) } else { name },
      if inherit { e.types.union(ty, auto) } else { ty },
      default: if inherit { auto } else { default },
      doc: doc,
      folds: false,
    )
  }
  (
    field(
      "source-indent",
      bool,
      false,
      "Align plain callouts to their source indentation, reserving the gutter columns. Pointed bubbles keep their character anchors.",
    ),
    field(
      "placement",
      e.types.union("above", "below"),
      "below",
      "Side of the source line on which to place the callout.",
    ),
    field(
      "bubble-gap",
      e.types.union(length, dictionary),
      0.5em,
      "Minimum separation: a length for both axes, or (x: length, y: length). Omitted axes default to 0.5em.",
    ),
    field(
      "pointer",
      e.types.option(int),
      none,
      "Character in the attached source line (one-based, like highlights; 0 means line start). `none` disables the bubble.",
    ),
    field(
      "pointer-align",
      e.types.union("start", "center", "end"),
      "center",
      "Preferred bubble alignment about the source character, clamped to the available row.",
    ),
    field("pointer-size", length, 0.4em, "Height and half-base width of the arrow."),
    field(
      "pointer-height",
      e.types.union(length, auto),
      auto,
      "Arrow height; auto uses pointer-size.",
    ),
    field(
      "pointer-width",
      e.types.union(length, auto),
      auto,
      "Full arrow base width; auto uses twice pointer-size.",
    ),
    field(
      "pointer-offset",
      length,
      0pt,
      "Horizontal shift from the source character; positive points right, negative left. Clamped to the bubble.",
    ),
    field(
      "bubble-align",
      alignment,
      center,
      "Alignment of the content inside the bubble, independent of cell alignment.",
    ),
    field(
      "bubble-fill",
      e.types.option(e.types.paint),
      luma(245),
      "Fill of the entire bubble and arrow.",
    ),
    field(
      "bubble-stroke",
      e.types.option(stroke),
      0.6pt + luma(80),
      "Stroke of the single bubble outline.",
    ),
    field(
      "bubble-inset",
      e.types.union(length, dictionary),
      (x: 0.5em, y: 0.3em),
      "Padding inside the bubble.",
    ),
    field(
      "bubble-outset",
      e.types.union(length, dictionary),
      0pt,
      "Extra paint extent around the padded body; reserved in the row.",
    ),
    field("bubble-radius", length, 2pt, "Corner radius of the bubble."),
    field(
      "bubble-width",
      e.types.union(length, ratio, auto),
      auto,
      "Preferred padded body width; auto fits the content, bounded by the row.",
    ),
  ).filter(f => f != none)
}

#let resolve(value, defaults, bubble-defaults: none) = {
  let result = (:)
  for name in ("source-indent", "placement", "pointer", ..style-names) {
    let local = value.at(name)
    let chosen = if local == auto { defaults.at(name) } else { local }
    if chosen == auto and bubble-defaults != none and name in style-names {
      chosen = bubble-defaults.at(bubble-name(name))
    }
    result.insert(name, chosen)
  }
  result
}

// Only mark requested characters. The markers occupy no width and survive
// syntax styles, highlights, native line breaks, and smart indentation.
#let annotate(body, data) = {
  let visit(body, offset) = {
    if body.has("label") and body.label == <codly-highlight> { return (body, offset) }
    if body.has("text") {
      let result = ()
      let part = ""
      for c in body.text.clusters() {
        let before = offset
        offset += c.len()
        part += c
        let targets = data.pointers.filter(p => before < p and p <= offset)
        if targets.len() > 0 {
          result.push(text(part))
          part = ""
          for pointer in targets {
            result.push(context [#metadata((
              owner: data.owner,
              row: data.row,
              pointer: pointer,
              advance: measure(text(c)).width / 2,
            ))<__codly-callout-anchor>])
          }
        }
      }
      result.push(text(part))
      (result.join(), offset)
    } else if body.has("children") {
      let result = ()
      for child in body.children {
        let (child, end) = visit(child, offset)
        result.push(child)
        offset = end
      }
      (result.join(), offset)
    } else if body.has("child") and body.has("styles") {
      let (child, end) = visit(body.child, offset)
      ((body.func())(child, body.styles), end)
    } else if body.has("body") {
      let args = body.fields()
      let (child, end) = visit(args.body, offset)
      args.body = child
      ((body.func())(..args), end)
    } else { (body, offset) }
  }
  let start = if 0 in data.pointers {
    [#metadata((
      owner: data.owner,
      row: data.row,
      pointer: 0,
      advance: 0pt,
    ))<__codly-callout-anchor>]
  } else { [] }
  start + visit(body, 0).first()
}

#let sides(value) = {
  let d = if type(value) == dictionary { value } else { (rest: value) }
  let rest = d.at("rest", default: 0pt)
  let side(name, axis) = d.at(name, default: d.at(axis, default: rest)).to-absolute()
  (
    left: side("left", "x"),
    right: side("right", "x"),
    top: side("top", "y"),
    bottom: side("bottom", "y"),
  )
}

// A single closed path avoids seams and shares one gradient/tiling coordinate
// system across the arrow and rounded rectangle.
#let outline(w, h, arrow, tip, radius, fill, stroke, arrow-width: auto, above: false) = {
  let r = calc.min(radius, w / 2, (h - arrow) / 2)
  let k = r * 0.5522847498
  let half = calc.min(if arrow-width == auto { arrow } else { arrow-width / 2 }, (w - 2 * r) / 2)
  let base = calc.min(w - r - half, calc.max(r + half, tip))
  let point(x, y) = (x, if above { h - y } else { y })
  curve(
    fill: fill,
    stroke: stroke,
    curve.move(point(r, arrow)),
    curve.line(point(base - half, arrow)),
    curve.line(point(tip, 0pt)),
    curve.line(point(base + half, arrow)),
    curve.line(point(w - r, arrow)),
    curve.cubic(point(w - r + k, arrow), point(w, arrow + r - k), point(w, arrow + r)),
    curve.line(point(w, h - r)),
    curve.cubic(point(w, h - r + k), point(w - r + k, h), point(w - r, h)),
    curve.line(point(r, h)),
    curve.cubic(point(r - k, h), point(0pt, h - r + k), point(0pt, h - r)),
    curve.line(point(0pt, arrow + r)),
    curve.cubic(point(0pt, arrow + r - k), point(r - k, arrow), point(r, arrow)),
    curve.close(),
  )
}

// Measure once at the full available row width, letting Typst wrap the body.
#let geometry(it, row-width, origin) = {
  assert(
    it.__anchor != none,
    message: "codly: pointed callouts need a source line; use the block's `callouts` field",
  )
  let anchor = query(<__codly-callout-anchor>).find(m => (
    m.value.owner == it.__anchor.owner and m.value.row == it.line and m.value.pointer == it.pointer
  ))
  let target = if anchor == none { 0pt } else {
    anchor.location().position().x - anchor.value.advance - origin.x
  }
  let inset = sides(it.at("bubble-inset"))
  let outset = sides(it.at("bubble-outset"))
  assert(
    (..inset.values(), ..outset.values()).all(v => v >= 0pt),
    message: "codly: bubble inset and outset must be non-negative",
  )
  let size = it.at("pointer-size").to-absolute()
  let arrow = it.at("pointer-height")
  let arrow = if arrow == auto { size } else { arrow.to-absolute() }
  let arrow-width = it.at("pointer-width")
  let arrow-width = if arrow-width == auto { 2 * size } else { arrow-width.to-absolute() }
  let radius = it.at("bubble-radius").to-absolute()
  assert(
    size >= 0pt and radius >= 0pt,
    message: "codly: pointer size and bubble radius must be non-negative",
  )
  assert(
    arrow >= 0pt and arrow-width >= 0pt,
    message: "codly: pointer height and width must be non-negative",
  )
  let stroke = it.at("bubble-stroke")
  let edge = if stroke == none { 0pt } else if stroke.thickness == auto { 0.5pt } else {
    stroke.thickness.to-absolute() / 2
  }
  let available = calc.max(0pt, row-width - 2 * edge)
  // Fit even deliberately oversized decorations into a narrow row.
  let decorations = inset.left + inset.right + outset.left + outset.right
  if decorations > available and decorations > 0pt {
    let scale = available / decorations
    inset.left *= scale
    inset.right *= scale
    outset.left *= scale
    outset.right *= scale
  }
  let horizontal = inset.left + inset.right
  let outer = outset.left + outset.right
  let natural = measure(it.body).width + horizontal
  let requested = it.at("bubble-width")
  let requested = if requested == auto { natural } else if type(requested) == ratio {
    row-width * requested
  } else { requested.to-absolute() }
  assert(requested >= 0pt, message: "codly: bubble width must be non-negative")
  let width = calc.min(calc.max(horizontal, requested), calc.max(0pt, available - outer))
  let body = block(width: width, inset: inset, above: 0pt, below: 0pt, breakable: false, align(
    it.at("bubble-align"),
    it.body,
  ))
  let body-height = measure(body).height
  let w = width + outer
  let h = body-height + outset.top + outset.bottom + arrow
  let desired = (
    target
      - if it.at("pointer-align") == "start" { 0pt } else if it.at("pointer-align") == "end" {
        w
      } else { w / 2 }
  )
  let x = calc.min(calc.max(edge, desired), calc.max(edge, row-width - edge - w))
  let tip = calc.min(w, calc.max(0pt, target + it.at("pointer-offset").to-absolute() - x))
  (
    x: x,
    w: w,
    h: h,
    edge: edge,
    arrow: arrow,
    arrow-width: arrow-width,
    tip: tip,
    radius: radius,
    outset: outset,
    body: body,
  )
}

#let paint(it, g) = {
  let above = it.placement == "above"
  block(
    width: g.w + 2 * g.edge,
    height: g.h + 2 * g.edge,
    above: 0pt,
    below: 0pt,
    breakable: false,
  )[
    #place(top + left, dx: g.edge, dy: g.edge, outline(
      g.w,
      g.h,
      g.arrow,
      g.tip,
      g.radius,
      it.at("bubble-fill"),
      it.at("bubble-stroke"),
      arrow-width: g.arrow-width,
      above: above,
    ))
    #place(
      top + left,
      dx: g.edge + g.outset.left,
      dy: g.edge + g.outset.top + if above { 0pt } else { g.arrow },
      g.body,
    )
  ]
}

#let render(it) = {
  if it.pointer == none { return it.body }
  if it.__layout != none { return paint(it, it.__layout) }
  block(width: 100%, above: 0pt, below: 0pt, breakable: false, layout(size => {
    let g = geometry(it, size.width, here().position())
    block(width: size.width, height: g.h + 2 * g.edge, above: 0pt, below: 0pt, breakable: false)[
      #place(top + left, dx: g.x - g.edge, paint(it, g))
    ]
  }))
}

// Show rules can inspect each bubble. Its styling is independent of the callout cell.
#let bubble-display(it) = {
  let row = (
    body: it.body,
    line: it.line,
    pointer: it.pointer,
    placement: it.placement,
    __anchor: it.__anchor,
    __layout: it.__layout,
  )
  for name in style-names { row.insert(name, it.at(bubble-name(name))) }
  render(row)
}

#let display(bubble, it) = {
  if it.pointer == none {
    if not it.source-indent { return it.body }
    return block(
      width: 100%,
      above: 0pt,
      below: 0pt,
      inset: (left: it.__indent),
      it.body,
    )
  }
  e.get(get => {
    let settings = resolve(it, it, bubble-defaults: get(bubble))
    let args = (:)
    for name in style-names { args.insert(bubble-name(name), settings.at(name)) }
    bubble(
      it.body,
      line: it.line,
      pointer: it.pointer,
      placement: it.placement,
      __anchor: it.__anchor,
      __layout: it.__layout,
      ..args,
    )
  })
}

#let pack(rows, constructor) = block(
  width: 100%,
  above: 0pt,
  below: 0pt,
  breakable: false,
  layout(size => {
    let origin = here().position()
    let lanes = ()
    for row in rows {
      let g = geometry(row, size.width, origin)
      let gap = row.at("bubble-gap")
      let gap = if type(gap) == dictionary { gap } else { (x: gap, y: gap) }
      assert(
        gap.keys().all(k => k in ("x", "y")),
        message: "codly: bubble gap accepts only x and y",
      )
      let spacing = gap.at("x", default: 0.5em)
      let vertical = gap.at("y", default: 0.5em)
      assert(
        type(spacing) == length and type(vertical) == length,
        message: "codly: bubble gap axes must be lengths",
      )
      let spacing = spacing.to-absolute()
      let vertical = vertical.to-absolute()
      assert(spacing >= 0pt and vertical >= 0pt, message: "codly: bubble gap must be non-negative")
      let a = g.x - g.edge
      let b = g.x + g.w + g.edge
      let overlap = (
        lanes.len() == 0
          or lanes
            .last()
            .items
            .any(item => (
              a < item.right + calc.max(spacing, item.gap)
                and b + calc.max(spacing, item.gap) > item.left
            ))
      )
      if overlap { lanes.push((items: (), height: 0pt, gap: 0pt)) }
      lanes.last().items.push((row: row, geometry: g, left: a, right: b, gap: spacing))
      lanes.last().height = calc.max(lanes.last().height, g.h + 2 * g.edge)
      lanes.last().gap = calc.max(lanes.last().gap, vertical)
    }
    let gaps = lanes.zip(lanes.slice(1)).map(((a, b)) => calc.max(a.gap, b.gap))
    let height = lanes.map(l => l.height).sum() + gaps.fold(0pt, (a, b) => a + b)
    block(width: size.width, height: height, above: 0pt, below: 0pt, breakable: false, {
      let y = 0pt
      for (index, lane) in lanes.enumerate() {
        if index > 0 { y += gaps.at(index - 1) }
        for item in lane.items {
          let row = item.row
          let body = row.remove("body")
          let dy = if row.placement == "above" {
            lane.height - item.geometry.h - 2 * item.geometry.edge
          } else { 0pt }
          place(top + left, dx: item.left, dy: y + dy, constructor(
            body,
            ..row,
            __layout: item.geometry,
          ))
        }
        y += lane.height
      }
    })
  }),
)

// Consecutive bubbles with identical cell styling can share a grid cell.
// Plain rows or different cell styles form a boundary, preserving their fills
// and spacing. Within a group, collision lanes retain declaration order.
#let row-cells(
  entries,
  constructor,
  defaults,
  owner,
  source-line,
  colspan,
  gutter-count: 0,
  source-text: "",
) = {
  let groups = ()
  for entry in entries {
    let settings = resolve(entry, defaults)
    for name in ("align", "breakable", "fill", "inset", "stroke") {
      let value = entry.at(name)
      settings.insert(name, if value == auto { defaults.at(name) } else { value })
    }
    let cell = (:)
    for name in ("align", "breakable", "fill", "inset", "stroke") {
      if settings.at(name) != auto { cell.insert(name, settings.at(name)) }
    }
    if settings.pointer != none { cell.insert("breakable", false) }
    let row = (body: entry.body, line: source-line, __anchor: (owner: owner), ..settings)
    if settings.source-indent and settings.pointer == none {
      let prefix = source-text.match(regex("^ *")).text
      row.insert("__indent", measure(text(prefix)).width)
    }
    if (
      settings.pointer != none
        and groups.len() > 0
        and groups.last().bubbles
        and groups.last().cell == cell
    ) {
      groups.last().rows.push(row)
    } else {
      groups.push((rows: (row,), bubbles: settings.pointer != none, cell: cell))
    }
  }
  groups.map(group => {
    let body = if not group.bubbles {
      let row = group.rows.first()
      let body = row.remove("body")
      constructor(body, ..row)
    } else { pack(group.rows, constructor) }
    if not group.bubbles and group.rows.first().source-indent {
      (
        (grid.cell([]),) * gutter-count
          + (grid.cell(body, colspan: colspan - gutter-count, ..group.cell),)
      )
    } else {
      (grid.cell(body, colspan: colspan, ..group.cell),)
    }
  })
}

/src/diff.typ:
#let language(lang) = {
  if lang == none or not lang.starts-with("diff,") { return none }
  let language = lang.slice(5).trim()
  assert(
    language != "" and not language.contains(","),
    message: "codly: diff requires one nonempty language after `diff,`",
  )
  language
}

// Each hunk has independent old/new syntax state. Metadata never enters either
// source view; within a hunk only the single patch prefix is removed.
#let parse(source, old-offset: 0, new-offset: 0) = {
  let source = source.split(regex("\r\n|\r|\n"))
  let patch = source.any(line => line.starts-with("diff --git ") or line.starts-with("@@"))
  assert(
    not source.any(line => (
      line.starts-with("diff --cc ")
        or line.starts-with("diff --combined ")
        or line.starts-with("@@@ ")
    )),
    message: "codly: combined merge diffs are not supported",
  )
  let rows = ()
  let groups = ((old: (), new: ()),)
  let old-number = old-offset + 1
  let new-number = new-offset + 1
  let old-left = 0
  let new-left = 0
  let in-hunk = false
  let hunk = regex("^@@ -([0-9]+)(?:,([0-9]+))? \\+([0-9]+)(?:,([0-9]+))? @@")
  for original in source {
    let kind = if original.starts-with("\\ No newline at end of file") { "meta" } else { "context" }
    let text = original
    if patch {
      let match = original.match(hunk)
      if match != none {
        assert(not in-hunk, message: "codly: incomplete unified diff hunk")
        if groups.last().old.len() > 0 or groups.last().new.len() > 0 {
          groups.push((old: (), new: ()))
        }
        old-number = int(match.captures.at(0)) + old-offset
        new-number = int(match.captures.at(2)) + new-offset
        let old-count = match.captures.at(1)
        let new-count = match.captures.at(3)
        old-left = if old-count == none { 1 } else { int(old-count) }
        new-left = if new-count == none { 1 } else { int(new-count) }
        in-hunk = old-left > 0 or new-left > 0
        kind = "meta"
      } else if original.starts-with("@@") {
        panic("codly: invalid unified diff hunk header")
      } else if original.starts-with("diff --git ") {
        assert(not in-hunk, message: "codly: incomplete unified diff hunk")
        in-hunk = false
        kind = "meta"
      } else if not in-hunk or original.starts-with("\\ No newline at end of file") {
        kind = "meta"
        assert(
          not original.starts-with(regex("^[ +\\-]"))
            or original.starts-with("--- ")
            or original.starts-with("+++ "),
          message: "codly: unified diff hunk counts do not match its lines",
        )
      }
    }
    if kind != "meta" {
      if original.starts-with("+") {
        kind = "added"
        text = original.slice(1)
      } else if original.starts-with("-") {
        kind = "removed"
        text = original.slice(1)
      } else if original.starts-with(" ") {
        text = original.slice(1)
      } else if patch {
        panic("codly: unified diff code lines must have a context, added, or removed prefix")
      }
    }
    let old = none
    let new = none
    let old-index = none
    let new-index = none
    if kind in ("removed", "context") {
      old = old-number
      old-number += 1
      old-index = groups.last().old.len()
      groups.last().old.push(text)
      if patch { old-left -= 1 }
    }
    if kind in ("added", "context") {
      new = new-number
      new-number += 1
      new-index = groups.last().new.len()
      groups.last().new.push(text)
      if patch { new-left -= 1 }
    }
    if patch {
      assert(
        old-left >= 0 and new-left >= 0,
        message: "codly: unified diff hunk counts do not match its lines",
      )
      if old-left == 0 and new-left == 0 { in-hunk = false }
    }
    rows.push((
      kind: kind,
      text: text,
      original: original,
      old: old,
      new: new,
      old-index: old-index,
      new-index: new-index,
      group: if kind == "meta" { none } else { groups.len() - 1 },
    ))
  }
  assert(not in-hunk, message: "codly: incomplete unified diff hunk")
  (rows: rows, groups: groups)
}

#let sublangs(segments, rows, group, side) = {
  if segments == none { return none }
  let mapped = ()
  for segment in segments {
    let indices = ()
    for (index, row) in rows.enumerate() {
      let at = row.at(side + "-index")
      if (
        index + 1 >= segment.start
          and index + 1 <= segment.end
          and row.group == group
          and at != none
      ) {
        indices.push(at + 1)
      }
    }
    if indices.len() > 0 {
      mapped.push((start: indices.first(), end: indices.last(), lang: segment.lang))
    }
  }
  mapped
}

#let resource(value, inherited, name) = {
  let safe = type(value) != str and (type(value) != array or value.all(v => type(v) != str))
  assert(
    safe or value == inherited,
    message: "codly: diff cannot copy an explicit string `raw."
      + name
      + "`; use `path(...)` or `read(..., encoding: none)`",
  )
  if safe { ((name): value) } else { (:) }
}

#let capture(tag, lines) = [#metadata((tag: tag, lines: lines))<__codly-diff-pass>]

// Re-enter Codly with a raw block for each syntax pass. Retain only styled
// raw.lines so references, callouts, and gutters render once.
#let prepare(source, args, settings, lang, constructor, style, column) = context {
  let origin = here()
  let model = parse(source.text, old-offset: settings.old-offset, new-offset: settings.new-offset)
  let resources = (
    resource(source.theme, style.theme, "theme")
      + resource(source.syntaxes, style.syntaxes, "syntaxes")
  )
  let base = args + (alias: none, __diff: none, diff: none)
  let make(text) = raw(
    text,
    block: true,
    lang: lang,
    align: source.align,
    tab-size: source.tab-size,
    ..resources,
  )
  set text(size: style.size)
  for (index, group) in model.groups.enumerate() {
    for side in ("old", "new") {
      let rows = group.at(side)
      if rows.len() == 0 { continue }
      constructor(
        make(rows.join("\n")),
        ..(
          base
            + (
              __diff-pass: (origin: origin, group: index, side: side),
              sublangs: sublangs(args.sublangs, model.rows, index, side),
            )
        ),
      )
    }
  }
  context {
    let passes = (:)
    for record in query(selector(<__codly-diff-pass>).after(origin).before(here())) {
      let tag = record.value.tag
      if tag.origin == origin {
        passes.insert(str(tag.group) + "-" + tag.side, record.value.lines)
      }
    }
    let lines = ()
    for (index, row) in model.rows.enumerate() {
      // Native raw.line text expands tabs. Keep that exact text paired with
      // its styled body so character highlights and pointers stay aligned.
      let text = if row.kind == "meta" { source.lines.at(index).text } else { row.text }
      let body = std.text(text)
      if row.group != none {
        let side = if row.kind == "removed" { "old" } else { "new" }
        let pass = passes.at(str(row.group) + "-" + side, default: ())
        let line = pass.at(row.at(side + "-index"), default: none)
        if line != none {
          text = line.text
          body = line.body
        }
      }
      lines.push(raw.line(index + 1, model.rows.len(), text, body))
    }
    let gutters = args.gutters
    if gutters == auto {
      gutters = ()
      for side in ("old", "new") {
        if settings.numbers and args.number-enabled {
          gutters.push(column(values: model.rows.map(row => row.at(side))))
        }
      }
      if settings.markers {
        gutters.push(column(
          values: model.rows.map(row => if row.kind == "added" {
            settings.added-marker
          } else if row.kind == "removed" { settings.removed-marker } else { none }),
          align: center,
        ))
      }
    }
    constructor(
      make(model.rows.map(row => row.text).join("\n")),
      ..(
        args
          + (
            __diff: (rows: model.rows, lines: lines, settings: settings, original: source.text),
            gutters: gutters,
            sublangs: none,
          )
      ),
    )
  }
}

#let fill(row, data) = {
  if row.kind != "code" or row.source-line == none { return auto }
  let diff = data.rows.at(row.source-line - 1)
  let fill = data.settings.at(diff.kind + "-fill")
  if type(fill) == function { fill(row + (diff: diff)) } else { fill }
}

/src/file.typ:
// File/source convenience input and reserved header/footer badge rows.
#let filename(value) = {
  if type(value) != path { return value }
  // Typst 0.15 exposes no path components. Its repr is path(<quoted string>),
  // including for package roots. Decode only that compiler-generated string;
  // always read the original path object, never reconstruct its root from repr.
  let shown = repr(value)
  assert(
    shown.starts-with("path(\"") and shown.ends-with("\")"),
    message: "codly: unsupported path representation; specify both file and lang explicitly",
  )
  let name = eval(shown.slice(5, -1), mode: "code")
  name.split("/").last()
}

#let extension(name) = {
  if type(name) != str { return none }
  let name = name.split("/").last()
  let parts = name.split(".")
  if parts.len() < 2 or parts.last() == "" or (parts.len() == 2 and parts.first() == "") {
    return none
  }
  lower(parts.last())
}

#let prepare(body, file: auto, lang: auto) = {
  let from-file = type(body) == path
  let source = from-file or type(body) == str
  let original-name = if from-file and (file == auto or lang == auto) { filename(body) }
  let file = if file == auto { original-name } else { filename(file) }
  if source {
    let code = if from-file { read(body) } else { body }
    let language = if lang == auto {
      extension(if from-file { original-name } else { file })
    } else { lang }
    body = if lang == auto and language == none { raw(code, block: true) } else {
      raw(code, block: true, lang: language)
    }
  }
  (body: body, file: file, source: source)
}

#let badge(it) = box(fill: it.fill, stroke: it.stroke, inset: it.inset, radius: it.radius, it.body)

// place does not reserve space by itself: wrap every badge in its measured
// box before putting the left/right groups into the header/footer grid.
#let reserved(body) = {
  let size = measure(body)
  box(width: size.width, height: size.height, place(top + left, body))
}

#let band(body, file: none, language: none, file-side: left, side: right) = {
  let lhs = ()
  let rhs = ()
  if file != none {
    if file-side == left { lhs.push(reserved(file)) } else { rhs.push(reserved(file)) }
  }
  if language != none {
    if side == left { lhs.push(reserved(language)) } else { rhs.push(reserved(language)) }
  }
  let group(items) = if items.len() == 0 { [] } else {
    grid(columns: (auto,) * items.len(), column-gutter: 0.5em, align: left + top, ..items)
  }
  let row = grid(
    columns: (auto, 1fr, auto),
    column-gutter: 0.5em,
    align: left + top,
    group(lhs), [], group(rhs),
  )
  if body == none or body == [] { row } else { stack(spacing: 0.5em, row, body) }
}


// Measure once, then reserve each side inside the actual code column. The
// inset participates in intrinsic width measurement and leaves later source
// rows at full width. Translated placements retain the badge's public outset.
#let inline-row(badges, padding) = {
  let measured = ()
  let reserved = (left: 0pt, right: 0pt)
  for badge in badges {
    let width = measure(badge.body).width
    let side = if badge.align.x == left { "left" } else { "right" }
    measured.push(badge + (side: side, offset: reserved.at(side)))
    if width > 0pt { reserved.at(side) += width + padding.left + padding.right }
  }
  let render = body => {
    let placements = measured
      .map(badge => place(
        badge.align,
        dx: badge.dx
          + if badge.side == "left" {
            badge.offset - reserved.left
          } else { reserved.right - badge.offset },
        dy: badge.dy,
        badge.body,
      ))
      .join()
    if reserved.left == 0pt and reserved.right == 0pt { return body + placements }
    layout(size => block(
      width: if size.width == calc.inf * 1pt { auto } else { size.width },
      inset: reserved,
      body + placements,
    ))
  }
  (render: render, left: reserved.left)
}

/src/geometry.typ:
#import "wrap.typ" as wrap

// Record cell bounds without measuring or duplicating their contents.
#let cell(body, origin, role: "body") = {
  let fields = if body.func() == grid.cell { body.fields() } else { (body: body) }
  let body = fields.remove("body")
  let fill = fields.remove("fill", default: auto)
  [#grid.cell(fill: none, ..fields, [#metadata((
      fill: fill,
      role: role,
      origin: origin,
    ))#body])<__codly-painted-cell>]
}

#let mark(it, fill, origin, code-column: 1, outside: true, guides: none) = {
  let first = if it.body.func() == metadata { it.body } else { it.body.children.first() }
  if first.value.origin != origin { return it }
  let paint = if first.value.fill == auto { fill(it.x, it.y - 1) } else { first.value.fill }
  if not outside or it.x >= code-column or it.colspan > 1 or paint != none {
    let marks = ()
    if guides != none and it.x == code-column and first.value.role == "body" {
      let depth = guides.depths.at(it.y - 1, default: 0)
      let inset = (
        guides.inset
          + guides.x-offset
          + guides.at("offsets", default: ()).at(it.y - 1, default: 0pt)
      ).to-absolute()
      for level in range(depth) {
        marks.push((
          x: inset + guides.step * level,
          color: guides.palette.at(calc.rem(level + guides.depth-offset, guides.palette.len())),
          thickness: guides.thickness,
          max-height: guides.max-height,
        ))
      }
    }
    place(top + left)[#metadata((
      kind: "cell-start",
      origin: origin,
      x: it.x,
      y: it.y,
      rowspan: it.rowspan,
      fill: paint,
      role: first.value.role,
      guides: marks,
    ))<__codly-geometry>]
    place(bottom + right)[#metadata((kind: "cell-end", origin: origin))<__codly-geometry>]
  }
  it
}

#let region-key(pos) = repr((pos.page, pos.x, pos.y))

#let pages(origin, code-column: 1, outside: true, wraps: none) = {
  let end = query(metadata.where(value: (kind: "paint-end", origin: origin)))
  if end.len() == 0 { return (:) }
  let starts = ()
  let ends = ()
  let tops = ()
  let bottoms = ()
  // Location equality also separates nested blocks at identical page positions.
  for mark in query(selector(<__codly-geometry>).after(origin).before(end.first().location())) {
    if mark.value.origin != origin { continue }
    if mark.value.kind == "cell-start" { starts.push(mark) } else if mark.value.kind == "cell-end" {
      ends.push(mark)
    } else if mark.value.kind == "region-start" { tops.push(mark) } else { bottoms.push(mark) }
  }
  if tops.len() != bottoms.len() { return (:) }
  let regions = ()
  let by-page = (:)
  for (i, top) in tops.enumerate() {
    let at = top.location().position()
    let bottom = bottoms.at(i).location().position().y
    let page = str(at.page)
    if page not in by-page { by-page.insert(page, ()) }
    by-page.at(page).push(i)
    regions.push((
      at: at,
      bottom: bottom,
      width: top.value.width,
      body-top: at.y,
      body-bottom: bottom,
      cells: (),
      numbers: (),
    ))
  }
  let spans = ()
  let rows = (:)
  let gutter = 0pt
  for (i, start) in starts.enumerate() {
    let a = start.location().position()
    let b = ends.at(i).location().position()
    let region = none
    for index in by-page.at(str(a.page), default: ()) {
      let r = regions.at(index)
      if a.x >= r.at.x and a.x < r.at.x + r.width and a.y >= r.at.y and a.y <= r.bottom {
        region = index
        break
      }
    }
    if region == none { continue }
    let value = start.value
    if value.role == "body" {
      spans.push((value: value, a: a, b: b, region: region))
      if value.x == code-column {
        rows.insert(str(value.y), (a: a, region: region))
        if outside { gutter = a.x - regions.at(region).at.x }
      }
    } else {
      regions.at(region).cells.push((a: a, b: b, fill: value.fill, guides: ()))
      if value.role == "header" {
        regions.at(region).body-top = calc.max(regions.at(region).body-top, b.y)
      }
      if value.role == "footer" {
        regions.at(region).body-bottom = calc.min(regions.at(region).body-bottom, a.y)
      }
    }
  }
  // A cell owns its fill until the next logical row, including continuation regions.
  for span in spans {
    let next = rows.at(str(span.value.y + span.value.rowspan), default: none)
    let last = if next == none { regions.len() - 1 } else { next.region }
    let index = span.region
    while index <= last {
      let r = regions.at(index)
      let top = if index == span.region { span.a.y } else { r.body-top }
      let bottom = if next != none and index == last { next.a.y } else { r.body-bottom }
      let dx = r.at.x - regions.at(span.region).at.x
      if bottom > top {
        let a = (x: span.a.x + dx, y: top)
        let b = (x: span.b.x + dx, y: bottom)
        if outside and span.value.x < code-column {
          regions.at(index).numbers.push((a: a, b: b, fill: span.value.fill))
        } else {
          let guides = if index == span.region { span.value.guides } else {
            span.value.guides.filter(g => g.max-height == none)
          }
          regions
            .at(index)
            .cells
            .push((
              a: a,
              b: b,
              fill: span.value.fill,
              guides: guides,
            ))
        }
      }
      index += 1
    }
  }
  let pages = (:)
  let markers = if wraps == none { () } else {
    wrap.marks(wraps.owner, end.first().location(), regions)
  }
  for r in regions {
    let local-markers = ()
    for marker in markers {
      let p = marker.at
      if (
        p.page != r.at.page
          or p.x < r.at.x
          or p.x > r.at.x + r.width
          or p.y < r.body-top
          or p.y >= r.body-bottom
      ) { continue }
      local-markers.push(marker)
    }
    pages.insert(region-key(r.at), (
      origin: r.at,
      left: r.at.x + gutter,
      top: r.at.y,
      bottom: r.bottom,
      cells: r.cells,
      numbers: r.numbers,
      wraps: local-markers,
    ))
  }
  pages
}

#let background(
  origin,
  width,
  radius,
  stroke,
  code-column: 1,
  outside: true,
  wraps: none,
  padding: (top: 0pt, right: 0pt, bottom: 0pt, left: 0pt),
  padding-fill: none,
) = context {
  let at = here().position()
  let page = pages(origin, code-column: code-column, outside: outside, wraps: wraps).at(
    region-key(at),
    default: none,
  )
  if page != none {
    for cell in page.numbers {
      if cell.fill != none {
        place(top + left, dx: cell.a.x - at.x, dy: cell.a.y - page.top, rect(
          width: cell.b.x - cell.a.x,
          height: cell.b.y - cell.a.y,
          fill: cell.fill,
          stroke: none,
        ))
      }
    }
    let code-left = (
      (if page.left == none { at.x } else { page.left }) - if outside { 0pt } else { padding.left }
    )
    let frame-top = page.top - padding.top
    place(top + left, dx: code-left - at.x, dy: frame-top - at.y, block(
      width: at.x + width - code-left + padding.right,
      height: page.bottom - page.top + padding.top + padding.bottom,
      radius: radius,
      stroke: stroke,
      clip: true,
      {
        // Paint only the new edge space: a block-wide fill would repaint
        // intentionally transparent rows, headers, and footers as well.
        if padding-fill != none {
          let frame-width = at.x + width - code-left + padding.right
          let frame-height = page.bottom - page.top + padding.top + padding.bottom
          for (x, y, w, h) in (
            (0pt, 0pt, frame-width, padding.top),
            (0pt, frame-height - padding.bottom, frame-width, padding.bottom),
            (
              0pt,
              padding.top,
              if outside { 0pt } else { padding.left },
              frame-height - padding.top - padding.bottom,
            ),
            (
              frame-width - padding.right,
              padding.top,
              padding.right,
              frame-height - padding.top - padding.bottom,
            ),
          ) {
            if w > 0pt and h > 0pt {
              place(top + left, dx: x, dy: y, rect(
                width: w,
                height: h,
                fill: padding-fill,
                stroke: none,
              ))
            }
          }
        }
        for cell in page.cells {
          if cell.fill != none {
            let x = calc.max(code-left, cell.a.x)
            place(top + left, dx: x - code-left, dy: cell.a.y - frame-top, rect(
              width: cell.b.x - x,
              height: cell.b.y - cell.a.y,
              fill: cell.fill,
              stroke: none,
            ))
          }
          for guide in cell.guides {
            let x = cell.a.x + guide.x
            if cell.a.x <= x and x < cell.b.x {
              place(top + left, dx: x - code-left, dy: cell.a.y - frame-top, pdf.artifact(line(
                end: (
                  0pt,
                  if guide.max-height == none { cell.b.y - cell.a.y } else {
                    calc.min(guide.max-height, cell.b.y - cell.a.y)
                  },
                ),
                stroke: guide.color + guide.thickness,
              )))
            }
          }
        }
      },
    ))
  }
}

#let wrap-foreground(origin, wraps) = context {
  let at = here().position()
  let start = none
  for record in query(selector(<__codly-geometry>).after(origin).before(here())) {
    if record.value.origin != origin or record.value.kind != "region-start" { continue }
    let position = record.location().position()
    if position.page == at.page and position.x == at.x { start = record }
  }
  if start == none { return }
  let position = start.location().position()
  let region = (
    page: at.page,
    x: position.x,
    top: position.y,
    bottom: at.y,
    width: start.value.width,
  )
  for marker in wrap.marks-region(wraps.owner, here(), region) {
    place(top + left, dx: marker.at.x - at.x, dy: marker.at.y - at.y, pdf.artifact(text(
      top-edge: "baseline",
      bottom-edge: "baseline",
      marker.body,
    )))
  }
}

#let outside(
  columns,
  inset,
  align,
  fill,
  stroke,
  radius,
  header,
  items,
  footer,
  code-column: 1,
  outside: true,
  guides: none,
  wraps: none,
  padding: (top: 0pt, right: 0pt, bottom: 0pt, left: 0pt),
  padding-fill: none,
  gutter: none,
  column-gutter: none,
  row-gutter: none,
) = context {
  let origin = here()
  let cells = ()
  for item in items { cells.push(cell(item, origin)) }
  let headers = ()
  if header.len() > 0 {
    let h = header.first()
    let fields = h.children.first().fields()
    fields.y = 1
    let body = fields.remove("body")
    headers.push(grid.header(repeat: h.repeat, level: 2, cell(
      grid.cell(..fields, body),
      origin,
      role: "header",
    )))
  }
  let footers = ()
  let end = grid.cell(colspan: columns.len(), inset: 0pt, [
    #metadata((kind: "region-end", origin: origin))<__codly-geometry>
    #if wraps != none { wrap-foreground(origin, wraps) }
  ])
  if footer.len() > 0 {
    let f = footer.first()
    let content = cell(f.children.first(), origin, role: "footer")
    if f.repeat {
      footers.push(grid.footer(repeat: true, content, end))
    } else {
      cells.push(content)
      footers.push(grid.footer(repeat: true, end))
    }
  } else {
    footers.push(grid.footer(repeat: true, end))
  }
  show <__codly-painted-cell>: it => mark(
    it,
    fill,
    origin,
    code-column: code-column,
    outside: outside,
    guides: guides,
  )
  let gutters = (:)
  if gutter != none { gutters.insert("gutter", gutter) }
  if column-gutter != none { gutters.insert("column-gutter", column-gutter) }
  if row-gutter != none { gutters.insert("row-gutter", row-gutter) }
  grid(
    columns: columns, inset: inset, align: align, stroke: none, fill: none,
    ..gutters,
    grid.header(repeat: true, level: 1, grid.cell(
      colspan: columns.len(),
      inset: 0pt,
      layout(size => {
        [#metadata((kind: "region-start", origin: origin, width: size.width))<__codly-geometry>]
        background(
          origin,
          size.width,
          radius,
          stroke,
          code-column: code-column,
          outside: outside,
          wraps: none,
          padding: padding,
          padding-fill: padding-fill,
        )
      }),
    )),
    ..headers, ..cells, ..footers,
  )
  metadata((kind: "paint-end", origin: origin))
}

/src/gutter.typ:
#import "@preview/elembic:1.1.1" as e

// `auto` is the existing number column, not a second numbering system.
#let columns(spec, enabled) = {
  let result = ()
  for column in (if spec == auto { (auto,) } else { spec }) {
    if column == auto {
      if enabled { result.push(auto) }
    } else { result.push(e.fields(column)) }
  }
  result
}

#let value(column, row) = {
  let values = column.values
  let value = if type(values) == function { values(row) } else if row.kind == "code" {
    values.at(row.source-line - 1, default: none)
  } else { none }
  assert(
    value == none or type(value) in (content, str, int, float),
    message: "codly: gutter values must be content, strings, numbers, or none",
  )
  value
}

#let cells(columns, row, number, constructor, parent) = {
  columns.map(column => {
    if column == auto { return constructor(number, parent) }
    let value = value(column, row)
    let fields = (:)
    for name in ("align", "inset", "stroke") {
      if column.at(name) != auto { fields.insert(name, column.at(name)) }
    }
    grid.cell(..fields, if value != none { text(..column.text)[#value] })
  })
}

// Resolve callbacks before layout, as with body fills. Header/footer cells
// own their paints; callouts span the gutters rather than creating gutter cells.
#let fills(columns, rows, body, number-fill, source: ()) = columns.map(column => rows.map(row => {
  if row.kind not in ("code", "skip") { return body.at(row.index, default: none) }
  let fill = if column == auto { number-fill } else { column.fill }
  if fill == auto { return body.at(row.index, default: none) }
  if type(fill) == array {
    assert(fill.len() > 0, message: "codly: gutter fill palettes must not be empty")
    return fill.at(calc.rem(row.index, fill.len()))
  }
  if type(fill) == function {
    return fill(
      row
        + (
          text: if row.source-line == none { none } else {
            source.at(row.source-line - 1, default: none)
          },
        ),
    )
  }
  fill
}))

/src/indent.typ:
// Work from raw.line.text: Typst has already normalized tabs and line endings.
// Syntax highlighting can split or wrap the leading whitespace arbitrarily.
#let leading-spaces = regex("^ *")

// Vote on observed changes, rather than taking a GCD that collapses to one
// after a single alignment outlier. Ties favor the smaller observed step.
#let detect(rows) = {
  let votes = (:)
  let previous = 0
  for row in rows {
    if row.blank { continue }
    let delta = calc.abs(row.columns - previous)
    if delta > 0 {
      let key = str(delta)
      votes.insert(key, votes.at(key, default: 0) + 1)
    }
    previous = row.columns
  }
  let width = 4
  let best = 0
  for (key, count) in votes {
    let candidate = int(key)
    if count > best or (count == best and candidate < width) {
      width = candidate
      best = count
    }
  }
  width
}

#let scan(lines, width: auto, blank-lines: true) = {
  let rows = lines.map(value => {
    let spaces = value.match(leading-spaces).text
    (columns: spaces.len(), blank: spaces.len() == value.len())
  })
  if width == auto { width = detect(rows) }
  let depths = ()
  let previous = 0
  let pending = 0
  for row in rows {
    if row.blank {
      pending += 1
      continue
    }
    let depth = int(calc.floor(row.columns / width))
    // Only continue levels shared by the surrounding nonblank lines. Leading
    // and trailing blank lines have no inferred guides, regardless of spaces.
    if pending > 0 {
      depths += (if blank-lines { calc.min(previous, depth) } else { 0 },) * pending
      pending = 0
    }
    depths.push(depth)
    previous = depth
  }
  depths += (0,) * pending
  (width: width, depths: depths)
}

#let settings(value, rainbow) = {
  let colored = if value.rainbow == auto { rainbow != none and rainbow.enabled } else {
    value.rainbow
  }
  let colors = if value.palette != auto { value.palette } else if rainbow != none {
    rainbow.palette
  } else {
    import "rainbow.typ": palette
    palette
  }
  let offset = if value.depth-offset != auto { value.depth-offset } else if rainbow != none {
    rainbow.depth-offset
  } else { 0 }
  (
    palette: if colored { colors } else { (value.color,) },
    depth-offset: offset,
